using Dentiva.Core.Entities;using Microsoft.EntityFrameworkCore;
namespace Dentiva.Infrastructure.Data;
public sealed class DentivaDbContext(DbContextOptions<DentivaDbContext> options):DbContext(options){
 public DbSet<Clinic> Clinics=>Set<Clinic>(); public DbSet<User> Users=>Set<User>(); public DbSet<Role> Roles=>Set<Role>(); public DbSet<Permission> Permissions=>Set<Permission>(); public DbSet<Patient> Patients=>Set<Patient>(); public DbSet<PatientMedicalHistory> MedicalHistories=>Set<PatientMedicalHistory>(); public DbSet<Visit> Visits=>Set<Visit>(); public DbSet<Appointment> Appointments=>Set<Appointment>(); public DbSet<TreatmentPlan> TreatmentPlans=>Set<TreatmentPlan>(); public DbSet<TreatmentPlanItem> TreatmentPlanItems=>Set<TreatmentPlanItem>(); public DbSet<ToothCondition> ToothConditions=>Set<ToothCondition>(); public DbSet<Prescription> Prescriptions=>Set<Prescription>(); public DbSet<PrescriptionItem> PrescriptionItems=>Set<PrescriptionItem>(); public DbSet<Invoice> Invoices=>Set<Invoice>(); public DbSet<InvoiceItem> InvoiceItems=>Set<InvoiceItem>(); public DbSet<Payment> Payments=>Set<Payment>(); public DbSet<Expense> Expenses=>Set<Expense>(); public DbSet<Staff> Staff=>Set<Staff>(); public DbSet<Attachment> Attachments=>Set<Attachment>(); public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();
 protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<Patient>().HasIndex(x=>x.PatientCode).IsUnique();b.Entity<Patient>().HasIndex(x=>x.FullName);b.Entity<Patient>().HasIndex(x=>x.Phone);b.Entity<Appointment>().HasIndex(x=>new{x.StartsAt,x.SerialNumber}).IsUnique();b.Entity<Invoice>().HasIndex(x=>x.InvoiceNumber).IsUnique();b.Entity<InvoiceItem>().Property(x=>x.UnitPrice).HasPrecision(18,2);b.Entity<Payment>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<Expense>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<TreatmentPlanItem>().Property(x=>x.EstimatedPrice).HasPrecision(18,2);}
}
